import { describe, expect, test } from "bun:test";
import { greet, add, slugify } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

describe("slugify", () => {
  test("converts mixed case with punctuation to lowercase hyphenated slug", () => {
    expect(slugify("Hello, World!")).toBe("hello-world");
  });

  test("normalizes spaces and underscores to single hyphens", () => {
    expect(slugify("  Foo__Bar  ")).toBe("foo-bar");
  });

  test("collapses multiple consecutive hyphens", () => {
    expect(slugify("a---b")).toBe("a-b");
  });

  test("preserves alphanumeric characters in lowercase", () => {
    expect(slugify("Test123")).toBe("test123");
  });

  test("trims leading and trailing hyphens", () => {
    expect(slugify("---trim---")).toBe("trim");
  });

  test("normalizes multiple spaces to single hyphens", () => {
    expect(slugify("multiple   spaces")).toBe("multiple-spaces");
  });

  test("removes special characters", () => {
    expect(slugify("Special!@#$%Chars")).toBe("specialchars");
  });

  test("handles empty string", () => {
    expect(slugify("")).toBe("");
  });
});

